/* Fourth Disaster workshop: fixed-version online entry. */
(()=>{
 const host=window.parent||window,doc=host.document;
 let disposed=false,loading=false;
 async function load(){
  if(disposed||loading)return;loading=true;doc.getElementById('fdw-online-error')?.remove();
  try{await import("https://cdn.jsdelivr.net/gh/xgdddl/fourth-disaster-panel@v1.3.11/workshop/index.js");}
  catch(error){
   console.warn('[第四天灾工坊加载]',error);if(disposed)return;
   const box=doc.createElement('div');box.id='fdw-online-error';box.setAttribute('role','alert');
   box.style.cssText='position:fixed;right:16px;bottom:18px;z-index:2147483647;max-width:360px;padding:14px;background:#242820;color:#f2e6c9;border:1px solid #b79a63;font:13px/1.7 sans-serif';
   const label=doc.createElement('p');label.textContent='创意工坊加载失败，草稿与已安装内容仍保留。请检查网络后重新加载。';box.append(label);
   const retry=doc.createElement('button');retry.textContent='重新加载';retry.addEventListener('click',load);box.append(retry);doc.body.append(box);
  }finally{loading=false;}
 }
 window.addEventListener('pagehide',()=>{disposed=true;doc.getElementById('fdw-online-error')?.remove();},{once:true});
 load();
})();
